// 1. Get the JSON data for the CURRENT item
const data = $input.item.json;

// 2. Define a default value
let stageNameFound = "Stage Not Found";

// 3. Check if opportunities and stages exist to prevent errors
if (data.opportunities && data.opportunities.length > 0 && data.stages) {

  // Get the ID from the first opportunity
  const targetId = data.opportunities[0].pipelineStageId;

  // Find the matching stage in the current item's stage list
  const matchingStage = data.stages.find(stage => stage.id === targetId);

  // If found, update the variable
  if (matchingStage) {
    stageNameFound = matchingStage.name;
  }
}

// 4. Add the result as a NEW field to your data
data.stage_name_result = stageNameFound;

// 5. Return the modified item
return $input.item;
